def wordPathExists(board, word):
    m, n = len(board), len(board[0])
    codes = [ord(ch) - 96 for ch in word]
    L = len(codes)
    have = {}
    for row in board:
        for x in row:
            have[x] = have.get(x, 0) + 1
    need = {}
    for x in codes:
        need[x] = need.get(x, 0) + 1
    for x, v in need.items():
        if have.get(x, 0) < v:
            return False
    if have.get(codes[0], 0) > have.get(codes[-1], 0):
        codes.reverse()
    seen = [[False] * n for _ in range(m)]

    def go(r, c, k):
        if board[r][c] != codes[k]:
            return False
        if k == L - 1:
            return True
        seen[r][c] = True
        found = False
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and not seen[nr][nc] and go(nr, nc, k + 1):
                found = True
                break
        seen[r][c] = False
        return found

    for r in range(m):
        for c in range(n):
            if go(r, c, 0):
                return True
    return False
